    # Create a 2D array for dynamic programming
    dp = [[[0 for _ in range(N)] for _ in range(N)] for _ in range(2)]

    # Process the grid in reverse order to populate the dp table
    for x, y, value in grid_values[::-1]:
        if x < N - 1:
            dp[x][y][0] = dp[x + 1][y][0] + value
        if x > 0:
            dp[x][y][1] = dp[x - 1][y][1] + value

    # Determine the paths
    path1, path2 = [0, 0], [0, 0]
    for x in range(N - 1):
        if dp[x][N - 1][0] > dp[x][N - 1][1]:
            path1[0], path1[1] = x, N - 1
        else:
            path2[0], path2[1] = x, N - 1

    # Continue backward to find the actual paths by checking the previous rows
    for j in range(N - 2, 0, -1):
        if dp[path1[0]][j][0] == dp[path1[0]][j + 1][0] + grid_values[j][0]:
            path1[0], path1[1] = j, path1[1]
        if dp[path2[0]][j][1] == dp[path2[0]][j + 1][1] + grid_values[j][0]:
            path2[0], path2[1] = j, path2[1]

    # Sum the values of the paths
    max_sum_path1 = 0
    for x in path1:
        max_sum_path1 += grid_values[x][2]

    max_sum_path2 = 0
    for x in path2:
        max_sum_path2 += grid_values[x][2]

    # Return the maximum sum of values collected
    return max(max_sum_path1, max_sum_path2)

