def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder or inorder == postorder:
        return inorder
    root = postorder[-1]
    index = inorder.rfind(root)
    left_inorder = inorder[:index]
    right_inorder = inorder[index+1:]
    left_postorder = postorder[:index]
    right_postorder = postorder[index+1:-1]
    return preorder_traversal(left_inorder, left_postorder) + root + preorder_traversal(right_inorder, right_postorder)

